mapper.select:
SELECT EXISTS (
    SELECT 1 FROM biz_group_member
    WHERE deal_id = #{dealId,jdbcType=OTHER} AND user_id = #{userId,jdbcType=OTHER}
      AND deleted = false
)

SELECT deal.id
FROM biz_group_deal deal
WHERE deal.deleted = false AND deal.status = 'open' AND deal.expire_time <= #{now}
  AND NOT EXISTS (
      SELECT 1
      FROM sys_scheduled_item_retry retry
      WHERE retry.job_key = 'team-expiry-sweep'
        AND retry.item_id = deal.id
        AND retry.deleted = false
        AND retry.retry_after > #{now}
  )
ORDER BY deal.expire_time, deal.id
LIMIT #{limit}
